INSERT INTO property_types(id,name) VALUES (1,'Квартира'),(2,'Студия'),(3,'Дом'),(4,'Комната');
INSERT INTO listings(owner_id,type_id,title,description,city,address,price,rooms,area,phone) VALUES
(2,1,'Светлая квартира рядом с парком','Однокомнатная квартира для длительной аренды. Есть мебель, холодильник и стиральная машина. До остановки пять минут пешком. Коммунальные платежи оплачиваются отдельно.','Москва','ул. Парковая, д. 12',42000,1,38,'+7 (000) 000-00-01'),
(2,2,'Уютная студия в новом доме','Студия с отдельной зоной кухни. Подойдёт одному человеку или паре. В доме есть лифт, рядом магазин. Залог за один месяц.','Санкт-Петербург','пр. Учебный, д. 8',30000,0,25,'+7 (000) 000-00-01'),
(2,1,'Двухкомнатная квартира для семьи','Две изолированные комнаты, просторная кухня и балкон. Рядом школа и детский сад. Договор заключается на длительный срок.','Казань','ул. Солнечная, д. 5',35000,2,56,'+7 (000) 000-00-01'),
(2,3,'Небольшой дом с участком','Дом с двумя спальнями, кухней и санузлом. Есть парковочное место. Отопление газовое. Подойдёт для спокойной жизни за городом.','Москва','пос. Лесной, д. 4',65000,3,85,'+7 (000) 000-00-01'),
(2,4,'Комната рядом с университетом','Отдельная комната в трёхкомнатной квартире. Кухня и санузел общие. Есть стол, шкаф и спальное место.','Казань','ул. Студенческая, д. 3',14000,1,16,'+7 (000) 000-00-01'),
(2,1,'Квартира с большой кухней','Чистая квартира после косметического ремонта. Два спальных места, рабочая зона, необходимая техника. Доступна для просмотра по договорённости.','Санкт-Петербург','ул. Тихая, д. 21',39000,1,43,'+7 (000) 000-00-01'),
(2,2,'Студия у набережной','Компактная студия с мебелью. Окна выходят во двор. Рядом набережная и остановка транспорта. Интернет оплачивается отдельно.','Казань','ул. Речная, д. 10',23000,0,24,'+7 (000) 000-00-01'),
(2,1,'Просторная квартира с балконом','Три комнаты, раздельный санузел и застеклённый балкон. У дома открытая парковка. Возможно проживание с детьми.','Москва','ул. Мирная, д. 17',78000,3,72,'+7 (000) 000-00-01');
